import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Teoremi","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/l_calcolo-delle-probabilita/lc/lch.md","filePath":"lezioni/l_calcolo-delle-probabilita/lc/lch.md"}`),a={name:`lezioni/l_calcolo-delle-probabilita/lc/lch.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="teoremi" tabindex="-1">Teoremi <a class="header-anchor" href="#teoremi" aria-label="Permalink to “Teoremi”">​</a></h1><blockquote><p>Quando si calcolano le probabilità di eventi quasi sempre è impossibile riferirsi a fatti sperimentali: ad esempio se devo calcolare la probabilità di fluttuazione di certe nuove azioni finanziarie non posso calcolarne la probabilità mediante fatti già accaduti (le azioni sono nuove) ma solamente con criteri che coinvolgano la conoscenza del possibile mercato presente e futuro.</p><p>Ciò porta a sviluppare il calcolo delle probabilità mediante metodi indiretti, cioè mediante proprietà che permetteranno di ridurre al minimo gli esperimenti:</p><p>Pertanto è importante sviluppare questi teoremi per un loro utilizzo nel calcolo.</p><p>Per completezza, siccome ora ci riferiamo alla probabilità assiomatica come sunto di tutte le probabilità già viste, dimostriamo, nel nuovo contesto, anche alcuni teoremi (probabilità totale, probabilità composta) che avevamo già visto validi per le singole probabilità.</p></blockquote><ul><li><a href="./lcha.html">Proprietà additiva</a></li><li><a href="./lchb.html">Probabilità condizionata</a></li><li><a href="./lchc.html">Proprietà moltiplicativa</a></li><li><a href="./lchd.html">Eventi indipendenti</a></li><li><a href="./lche.html">Probabilità totale</a></li><li><a href="./lchf.html">Formula di Bayes</a></li></ul>`,3)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};